from itertools import permutations

def solve_qg3(n=7):
    # We need an n×n Latin square with:
    # 1. x[i][i] = i (idempotent)
    # 2. x[x[i][j]][x[j][i]] = i (QG3)

    # Use backtracking with constraint propagation
    # x is represented as a flat list of n*n values

    x = [None] * (n * n)

    # Set diagonal
    for i in range(n):
        x[i * n + i] = i

    # Track row and column usage
    row_used = [set() for _ in range(n)]
    col_used = [set() for _ in range(n)]

    for i in range(n):
        row_used[i].add(i)
        col_used[i].add(i)

    def get(i, j):
        return x[i * n + j]

    def set_val(i, j, v):
        x[i * n + j] = v
        row_used[i].add(v)
        col_used[j].add(v)

    def unset_val(i, j, v):
        x[i * n + j] = None
        row_used[i].discard(v)
        col_used[j].discard(v)

    def check_qg3(i, j):
        # Check x[x[i][j]][x[j][i]] = i
        a = get(i, j)
        b = get(j, i)
        if a is None or b is None:
            return True  # Can't check yet
        c = get(a, b)
        if c is None:
            return True  # Can't check yet
        return c == i

    def check_all_qg3():
        for i in range(n):
            for j in range(n):
                if not check_qg3(i, j):
                    return False
        return True

    # Get cells to fill (non-diagonal)
    cells = [(i, j) for i in range(n) for j in range(n) if i != j]

    def backtrack(idx):
        if idx == len(cells):
            return check_all_qg3()

        i, j = cells[idx]

        for v in range(n):
            if v in row_used[i] or v in col_used[j]:
                continue

            set_val(i, j, v)

            # Check QG3 constraints that might now be fully determined
            valid = True
            # Check (i,j): need x[i][j], x[j][i], x[x[i][j]][x[j][i]]
            # Check (j,i): need x[j][i], x[i][j], x[x[j][i]][x[i][j]]
            # Also check any (a,b) where x[a][b]=i or x[b][a]=i might be affected

            # Simple check: verify all constraints that are now fully determined
            for pi in range(n):
                for pj in range(n):
                    a = get(pi, pj)
                    b = get(pj, pi)
                    if a is not None and b is not None:
                        c = get(a, b)
                        if c is not None and c != pi:
                            valid = False
                            break
                if not valid:
                    break

            if valid:
                if backtrack(idx + 1):
                    return True

            unset_val(i, j, v)

        return False

    if backtrack(0):
        return x
    return None

