def solve_small(n, find_all=False):
    results = []

    def backtrack(grid, row):
        if row == n:
            if check_qg3_grid(grid, n):
                results.append([r[:] for r in grid])
            return

        for perm in permutations(range(n)):
            if perm[row] != row:  # idempotent
                continue
            # Check column constraints
            col_ok = True
            for j in range(n):
                col_vals = [grid[i][j] for i in range(row)] + [perm[j]]
                if len(set(col_vals)) != len(col_vals):
                    col_ok = False
                    break
            if not col_ok:
                continue

            # Early QG3 check: for all i < row and j <= row, check if constraint is determined
            grid.append(list(perm))

            # Check QG3 for pairs where all three values are known
            valid = True
            for i in range(row + 1):
                for j in range(row + 1):
                    a = grid[i][j]
                    b = grid[j][i]
                    if a < row + 1 and b < row + 1:
                        c = grid[a][b]
                        if c != i:
                            valid = False
                            break
                if not valid:
                    break

            if valid:
                backtrack(grid, row + 1)
                if results and not find_all:
                    grid.pop()
                    return

            grid.pop()

    backtrack([], 0)
    return results

